tool_input.old_string:
fillBasicExample() {
  const baseInfoForm = this.$refs.baseInfoForm
  if (!baseInfoForm || !this.currentCompanyType) return
  const idType = (baseInfoForm.legalPersonCertificateTypeOptions || []).find((item) => item.dictLabel === '居民身份证')
  const example = {
    uniformSocialCreditCode: '91320585MA1WX2K34X',
    companyName: '太仓市晨光置业有限公司',
    legalRepresentative: '陈立明',
    corporateIdNo: '320585198605120018'
  }
  if (idType) example.legalPersonCertificateType = idType.dictValue
  Object.assign(baseInfoForm.form, example)
  this.$nextTick(() => baseInfoForm.$refs.form.clearValidate())
  this.$message.info('示例数据已填入，可直接生成临时账号')
},

tool_input.new_string:
fillBasicExample() {
  const baseInfoForm = this.$refs.baseInfoForm
  if (!baseInfoForm) return
  if (!this.currentCompanyType) {
    this.alreadyChooseCompanyType({ dictValue: '01', remark: '040100' })
  }
  const idType = (baseInfoForm.legalPersonCertificateTypeOptions || []).find((item) => item.dictLabel === '居民身份证')
  const example = {
    uniformSocialCreditCode: '91320585MA1WX2K34X',
    companyName: '太仓市晨光置业有限公司',
    legalRepresentative: '陈立明',
    corporateIdNo: '320585198605120018'
  }
  if (idType) example.legalPersonCertificateType = idType.dictValue
  Object.assign(baseInfoForm.form, example)
  this.$nextTick(() => {
    baseInfoForm.$refs.form.clearValidate()
    const creditCodeInput = baseInfoForm.$el.querySelector('[data-testid="registration-uscc-input"] input')
    if (creditCodeInput) creditCodeInput.focus()
  })
  this.$message.info('示例数据已填入，可直接生成临时账号')
},

const fillStart = registration.indexOf('fillBasicExample()')
const fillEnd = registration.indexOf('createTempRegistrationAccount()', fillStart)
const method = fillStart >= 0 && fillEnd > fillStart ? registration.slice(fillStart, fillEnd) : ''
